def is_nested(string):
    '''
    Create a function that takes a string as input which contains only square brackets.
    The function should return True if and only if there is a valid subsequence of brackets 
    where at least one bracket in the subsequence is nested.
    '''
    # Find the first '['
    first_open = None
    for i, c in enumerate(string):
        if c == '[':
            first_open = i
            break

    if first_open is None:
        return False

    # Find the second '[' after the first one
    second_open = None
    for i in range(first_open + 1, len(string)):
        if string[i] == '[':
            second_open = i
            break

    if second_open is None:
        return False

    # Find the first ']' after the second '['
    first_close = None
    for i in range(second_open + 1, len(string)):
        if string[i] == ']':
            first_close = i
            break

    if first_close is None:
        return False

    # Find the second ']' after the first ']'
    second_close = None
    for i in range(first_close + 1, len(string)):
        if string[i] == ']':
            second_close = i
            break

    if second_close is None:
        return False

    # We found the pattern [ [] ] as a subsequence, which means nesting exists
    return True
