def max_sum_bitonic_subsequence(arr):
    if not arr:
        return 0

    n = len(arr)
    inc = [0] * n
    dec = [0] * n

    # Compute maximum increasing subsequence sum ending at each index
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Compute maximum decreasing subsequence sum starting at each index
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find the maximum bitonic sum
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum


