def even_bit_set_number(n):
    if n == 0:
        return 0

    # Find the number of bits in the binary representation
    num_bits = n.bit_length()

    # Create a mask with even bit positions from the left set to 1
    mask = 0
    for i in range(num_bits):
        if i % 2 == 0:
            mask |= (1 << (num_bits - 1 - i))

    # Set all even-positioned bits from the left to 1
    return n | mask

