def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # inc[i] = maximum sum of an increasing subsequence ending at index i
    inc = [arr[i] for i in range(n)]
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i] = maximum sum of a decreasing subsequence starting at index i
    dec = [arr[i] for i in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Maximum bitonic subsequence sum
    max_bitonic = max(inc[i] + dec[i] - arr[i] for i in range(n))
    return max_bitonic


